python -c 'from zipfile import ZipFile; from lxml import etree; p="/work/complaint_preparation.docx"; z=ZipFile(p); ns={"w":"http://schemas.openxmlformats.org/wordprocessingml/2006/main"}; xml=etree.fromstring(z.read("word/document.xml")); sx=etree.fromstring(z.read("word/styles.xml")); bad=[]; counts={"SimHei":0,"FangSong":0};
for r in xml.xpath("//w:r",namespaces=ns):
 t="".join(r.xpath(".//w:t/text()",namespaces=ns)); rp=r.find("w:rPr",ns); rf=rp.find("w:rFonts",ns) if rp is not None else None; vals=[rf.get("{%s}%s"%(ns["w"],a)) if rf is not None else None for a in ("ascii","hAnsi","eastAsia","cs")];
 if "民事起诉状" in t or "施某诉白某微信购表未交货纠纷" in t: expected="SimHei"
 else: expected="FangSong"
 if any(v!=expected for v in vals): bad.append((t[:40],expected,vals))
 else: counts[expected]+=1
for name in ("Title","Heading1","Heading2","Heading3"):
 el=sx.xpath("//w:style[@w:styleId=$s]",namespaces=ns,s=name); print(name,[(el0.xpath("string(w:rPr/w:rFonts/@w:ascii)",namespaces=ns),el0.xpath("string(w:rPr/w:rFonts/@w:hAnsi)",namespaces=ns),el0.xpath("string(w:rPr/w:rFonts/@w:eastAsia)",namespaces=ns),el0.xpath("string(w:rPr/w:rFonts/@w:cs)",namespaces=ns)) for el0 in el])
print("run-font-counts",counts,"bad-runs",bad[:12],"total",sum(counts.values())+len(bad)); print("zip-ok",z.testzip() is None)'

python -c 'from zipfile import ZipFile; from lxml import etree; z=ZipFile("/work/complaint_preparation.docx"); ns={"w":"http://schemas.openxmlformats.org/wordprocessingml/2006/main"}; x=etree.fromstring(z.read("word/document.xml")); bad=[]; totals={"SimHei":0,"FangSong":0};
for p in x.xpath("//w:body/w:p",namespaces=ns):
 sid=p.xpath("string(w:pPr/w:pStyle/@w:val)",namespaces=ns); text="".join(p.xpath(".//w:t/text()",namespaces=ns)); heading=sid in ("Title","Heading1","Heading2","Heading3") or text.strip()=="民事起诉状"
 expected="SimHei" if heading else "FangSong"
 for r in p.xpath("./w:r",namespaces=ns):
  rp=r.find("w:rPr",ns); rf=rp.find("w:rFonts",ns) if rp is not None else None; attrs=[rf.get("{%s}%s"%(ns["w"],a)) if rf is not None else None for a in ("ascii","hAnsi","eastAsia","cs")]; rt="".join(r.xpath(".//w:t/text()",namespaces=ns));
  if any(a!=expected for a in attrs): bad.append((sid,text[:30],rt[:30],attrs,expected))
  else: totals[expected]+=1
for t in x.xpath("//w:tbl",namespaces=ns):
 for r in t.xpath(".//w:r",namespaces=ns):
  rp=r.find("w:rPr",ns); rf=rp.find("w:rFonts",ns) if rp is not None else None; attrs=[rf.get("{%s}%s"%(ns["w"],a)) if rf is not None else None for a in ("ascii","hAnsi","eastAsia","cs")];
  if any(a!= "FangSong" for a in attrs): bad.append(("table","".join(r.xpath(".//w:t/text()",namespaces=ns))[:30],attrs))
  else: totals["FangSong"]+=1
print("all-runs-explicit-fonts:",totals,"violations:",bad,"zip integrity:",z.testzip())'

